//! Day-count parity tests against `data/daycount_quantlib.json`.
//!
//! The fixture is regenerated by `generate_daycount_quantlib.py` (next to this
//! file), which runs QuantLib. Each `source: "quantlib"` case records the
//! exact QuantLib day counter (`quantlib_convention`) and, for 30E/360 ISDA,
//! the termination input; `source: "hand"` cases (ACT/ACT ICMA, ACT/365L) are
//! hand-computed from the accepted formulas. Every case runs through the
//! public `DayCount::year_fraction`; for the 30/360 family the synthetic day
//! count is checked as `year_fraction * 360`.

use finstack_quant_core::dates::{Date, DayCount, DayCountContext, Tenor};
use finstack_quant_test_utils::golden::{GoldenSuite, load_suite_from_path};
use finstack_quant_test_utils::golden_path;
use serde::Deserialize;
use time::Month;

/// Expected values for a single day count test case.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct DayCountExpected {
    /// Synthetic 30/360 day count (QuantLib `dayCount`).
    #[serde(default)]
    days: Option<i64>,
    /// Actual elapsed days (documentation for actual-day cases).
    #[serde(default)]
    #[allow(dead_code)]
    actual_days: Option<i64>,
    year_fraction: f64,
    tolerance: f64,
}

/// A single day count test case from the golden fixture.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
#[allow(dead_code)] // provenance fields are documentation
struct DayCountCase {
    id: String,
    description: String,
    /// `quantlib` (computed by QuantLib) or `hand` (hand-computed formula).
    source: String,
    convention: String,
    /// Exact QuantLib day counter used for a `quantlib` case.
    #[serde(default)]
    quantlib_convention: Option<String>,
    start_date: String,
    end_date: String,
    /// 30E/360 ISDA termination status of the later endpoint.
    #[serde(default)]
    end_is_termination_date: Option<bool>,
    /// Coupon frequency for ACT/ACT ICMA (e.g. "6M", "3M", "1Y", "1M").
    #[serde(default)]
    frequency: Option<String>,
    /// Reference (ICMA) or enclosing (ACT/365L) coupon period.
    #[serde(default)]
    coupon_period: Option<(String, String)>,
    expected: DayCountExpected,
    #[serde(default)]
    notes: Option<String>,
}

/// Parse a date string in "YYYY-MM-DD" format.
fn parse_date(s: &str) -> Date {
    let parts: Vec<&str> = s.split('-').collect();
    assert_eq!(
        parts.len(),
        3,
        "Invalid date format '{}': expected YYYY-MM-DD",
        s
    );
    let year: i32 = parts[0]
        .parse()
        .unwrap_or_else(|_| panic!("Invalid year in date '{}'", s));
    let month: u8 = parts[1]
        .parse()
        .unwrap_or_else(|_| panic!("Invalid month in date '{}'", s));
    let day: u8 = parts[2]
        .parse()
        .unwrap_or_else(|_| panic!("Invalid day in date '{}'", s));
    Date::from_calendar_date(year, Month::try_from(month).unwrap(), day)
        .unwrap_or_else(|_| panic!("Invalid calendar date '{}'", s))
}

/// Map a canonical convention label to `DayCount`.
fn parse_convention(s: &str) -> DayCount {
    s.parse()
        .unwrap_or_else(|err| panic!("unknown convention {s}: {err}"))
}

/// Parse frequency string to Tenor (e.g., "6M" -> semi-annual, "3M" -> quarterly).
fn parse_frequency(s: &str) -> Option<Tenor> {
    match s {
        "1M" => Some(Tenor::monthly()),
        "3M" => Some(Tenor::quarterly()),
        "6M" => Some(Tenor::semi_annual()),
        "1Y" => Some(Tenor::annual()),
        _ => None,
    }
}

#[test]
fn test_daycount_quantlib_parity() {
    let path = golden_path!("data/daycount_quantlib.json");
    let suite: GoldenSuite<DayCountCase> =
        load_suite_from_path(path).expect("Failed to load daycount golden suite");

    assert_eq!(suite.meta.suite_id, "daycount_quantlib_parity");
    assert!(!suite.cases.is_empty(), "Suite should have test cases");

    let failures: Vec<String> = suite
        .cases
        .iter()
        .filter_map(|case| {
            check_case(case)
                .err()
                .map(|e| format!("[{}] {}: {}", case.id, case.description, e))
        })
        .collect();

    assert!(
        failures.is_empty(),
        "QuantLib parity test failures ({}):\n{}",
        failures.len(),
        failures.join("\n")
    )
}

/// Check one case through the public `DayCount` interval API.
fn check_case(case: &DayCountCase) -> Result<(), String> {
    assert!(
        matches!(case.source.as_str(), "quantlib" | "hand"),
        "unknown source {}",
        case.source
    );
    let start = parse_date(&case.start_date);
    let end = parse_date(&case.end_date);
    let day_count = parse_convention(&case.convention);
    let ctx = DayCountContext {
        calendar: None,
        frequency: case.frequency.as_deref().and_then(parse_frequency),
        bus_basis: None,
        coupon_period: case
            .coupon_period
            .as_ref()
            .map(|(s, e)| (parse_date(s), parse_date(e))),
        end_is_termination_date: case.end_is_termination_date,
    };

    let yf = day_count
        .year_fraction(start, end, ctx)
        .map_err(|e| format!("year_fraction failed: {}", e))?;

    let expected_yf = case.expected.year_fraction;
    if (yf - expected_yf).abs() > case.expected.tolerance {
        return Err(format!(
            "year_fraction mismatch: expected {:.15}, got {:.15} (diff: {:.2e})",
            expected_yf,
            yf,
            (yf - expected_yf).abs()
        ));
    }
    if let Some(days) = case.expected.days {
        let synthetic = yf * 360.0;
        if (synthetic - days as f64).abs() > 1e-9 {
            return Err(format!(
                "synthetic day count mismatch: expected {days}, got {synthetic}"
            ));
        }
    }
    Ok(())
}

/// Test Act/Act ISDA year boundary splitting.
/// This is critical for swap valuation accuracy.
#[test]
fn test_actact_isda_year_boundary_splitting() {
    let ctx = DayCountContext::default();

    // Period spanning from leap year to non-leap year
    let start = Date::from_calendar_date(2024, Month::July, 1).unwrap();
    let end = Date::from_calendar_date(2026, Month::January, 1).unwrap();

    let yf = DayCount::ActAct.year_fraction(start, end, ctx).unwrap();

    // Expected: 184/366 (H2 2024) + 365/365 (full 2025)
    // = 0.5027322404... + 1.0 = 1.5027322404...
    let expected = 184.0 / 366.0 + 1.0;

    assert!(
        (yf - expected).abs() < 1e-12,
        "Act/Act ISDA spanning years: expected {:.15}, got {:.15}",
        expected,
        yf
    );
}
